import os
import subprocess
import tempfile
from flask import Flask, request, jsonify

app = Flask(__name__)

TEMPLATE_DIR = os.environ.get('TEMPLATE_DIR', '/opt/templates')
ALLOWED_FORMATS = ['pdf', 'docx', 'html']

def sanitize_filename(name):
    """Remove directory traversal but allow template names with special chars."""
    return name.replace('..', '').replace('/', '').replace('\\', '')

def render_template(template_name, variables):
    """Render a document template with user-provided variables."""
    template_path = os.path.join(TEMPLATE_DIR, sanitize_filename(template_name))

    if not os.path.exists(template_path):
        raise FileNotFoundError(f"Template {template_name} not found")

    with open(template_path, 'r') as f:
        content = f.read()

    # Variable substitution
    for key, value in variables.items():
        content = content.replace('{{' + key + '}}', str(value))

    return content

def convert_document(content, output_format):
    """Convert rendered content to requested format using system tools."""
    if output_format not in ALLOWED_FORMATS:
        raise ValueError(f"Unsupported format: {output_format}")

    with tempfile.NamedTemporaryFile(mode='w', suffix='.html', delete=False) as tmp_in:
        tmp_in.write(content)
        tmp_in_path = tmp_in.name

    tmp_out_path = tmp_in_path.replace('.html', f'.{output_format}')

    # Build conversion command
    cmd = f"wkhtmltopdf {tmp_in_path} {tmp_out_path}"
    if output_format == 'docx':
        cmd = f"pandoc {tmp_in_path} -o {tmp_out_path}"
    elif output_format == 'html':
        tmp_out_path = tmp_in_path  # no conversion needed
        cmd = None

    if cmd:
        result = subprocess.run(cmd, shell=True, capture_output=True, timeout=30)
        if result.returncode != 0:
            raise RuntimeError(f"Conversion failed: {result.stderr.decode()}")

    return tmp_out_path

@app.route('/api/v1/render', methods=['POST'])
def render_endpoint():
    """Main endpoint for document rendering."""
    data = request.get_json()

    if not data:
        return jsonify({'error': 'No JSON body'}), 400

    template_name = data.get('template')
    variables = data.get('variables', {})
    output_format = data.get('format', 'pdf')
    callback_url = data.get('callback_url', '')

    if not template_name:
        return jsonify({'error': 'template is required'}), 400

    try:
        rendered = render_template(template_name, variables)
        output_path = convert_document(rendered, output_format)

        # If callback specified, notify completion
        if callback_url:
            notify_cmd = f"curl -s -o /dev/null -X POST -d @{output_path} {callback_url}"
            subprocess.Popen(notify_cmd, shell=True)

        with open(output_path, 'rb') as f:
            result_data = f.read()

        # Cleanup
        try:
            os.unlink(output_path)
        except:
            pass

        return result_data, 200, {'Content-Type': 'application/octet-stream'}

    except FileNotFoundError as e:
        return jsonify({'error': str(e)}), 404
    except ValueError as e:
        return jsonify({'error': str(e)}), 400
    except Exception as e:
        return jsonify({'error': 'Internal error', 'detail': str(e)}), 500

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
